"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["66209"],{85901(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.ja_ativo","status":422,"titulo":"O modelo de formul\xe1rio j\xe1 est\xe1 ativo"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.ja_ativo","requisitos":[],"oQueAconteceu":["A ativa\xe7\xe3o (`POST /api/configuracao/admin/modelos-formulario/{id}/ativacao`) foi pedida para um modelo de formul\xe1rio que j\xe1 est\xe1 ativo. O modelo nasce desativado, e a ativa\xe7\xe3o o p\xf5e na escolha dos processos novos. A opera\xe7\xe3o deixa registro de auditoria, e aceitar uma ativa\xe7\xe3o sem efeito gravaria uma mudan\xe7a que n\xe3o houve; por isso a repeti\xe7\xe3o \xe9 recusada.","A busca do modelo vem antes: com um `{id}` que n\xe3o existe, a resposta \xe9 [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado), e s\xf3 um modelo existente chega a esta confer\xeancia. Nada \xe9 gravado."],"comoResolver":["Nenhuma provid\xeancia \xe9 necess\xe1ria: o modelo j\xe1 est\xe1 ativo e dispon\xedvel para processos novos. Se a inten\xe7\xe3o era outra, confira o identificador do modelo."],"ondeAparece":["Ativa\xe7\xe3o de um modelo de formul\xe1rio"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);